from taf.collectors.core.entities.collector import CommonOamCollector
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CommonInfomodelCollector(CommonOamCollector):
    def __init__(
            self,
            timeout=480,
            target_file_name=None,
            **kwargs):
        super(CommonInfomodelCollector, self).__init__(**kwargs)
        self._timeout = float(timeout)
        self._target_file_name = self._default_target_file_name if target_file_name is None else target_file_name

    def _collect(self, target_dir):
        """
            Transfer the information, that shall be collected, from the remote host to the local host.

            :param str target_dir: target path, where collected information shall be stored on the local host
        """
        target_file_path = "{target_dir}/{target_file_name}".format(
            target_dir=target_dir,
            target_file_name=self._target_file_name)
        logger.debug(
            "collect infomodel {log_type}, target file path={target_file_path},"
            " timeout={timeout}".format(
                log_type=self._log_type,
                target_file_path=target_file_path,
                timeout=self._timeout))
        getattr(self._managed_admin_connection, self._admin_connection_method)(
            target_file_name=target_file_path,
            timeout=self._timeout)


class CoamIMSnapshotCollector(CommonInfomodelCollector):
    """
    Creates cOAM REST API based IM snapshot collector.

    Generation of a IM snapshot is triggered at the REST API and the result is stored locally in the directory
    target_dir, that is given to the collect() call.
    """
    _default_target_file_name = "im_snapshot.ims2"
    _log_type = "snapshot"
    _admin_connection_method = "collect_im_snapshot"


class CoamIMLogCollector(CommonInfomodelCollector):
    """
    Creates cOAM REST API based IM Log collector.

    Generation of a IM log is triggered at the REST API and the result is stored locally in the directory
    target_dir, that is given to the collect() call.
    """
    _default_target_file_name = "im_log.ims2"
    _log_type = "log"
    _admin_connection_method = "collect_infomodel_log_from_current_session"
